"""lotus: tpch/Q30; common numeric v4; explicitly rewritten workload.
Source: original/tpch/plop/Q30.sql
Run via experiments.validation.faithful_runtime; model settings are external.
"""
SYSTEM = 'lotus'
QUERY_ID = 'tpch/Q30'
SOURCE = 'original/tpch/plop/Q30.sql'

RELATIONAL_SQL = "WITH orders_lineitem_customer AS (\n  SELECT\n    l.l_orderkey,\n    l.l_partkey,\n    l.l_suppkey,\n    l.l_quantity,\n    l.l_extendedprice,\n    l.l_discount,\n    l.l_shipmode,\n    o.o_orderdate,\n    o.o_orderpriority,\n    o.o_totalprice,\n    c.c_custkey,\n    c.c_name,\n    c.c_mktsegment,\n    c.c_acctbal\n  FROM lineitem AS l\n  JOIN orders AS o\n    ON o.o_orderkey = l.l_orderkey\n  JOIN customer AS c\n    ON c.c_custkey = o.o_custkey\n  WHERE\n    l.l_shipmode IN ('AIR', 'REG AIR', 'TRUCK')\n    AND l.l_quantity BETWEEN 12 AND 30\n    AND l.l_discount BETWEEN 0.04 AND 0.07\n    AND o.o_orderdate >= CAST('1996-01-01' AS DATE)\n    AND o.o_orderdate < CAST('1998-01-01' AS DATE)\n    AND o.o_totalprice BETWEEN 60000 AND 170000\n    AND c.c_mktsegment IN ('FURNITURE', 'HOUSEHOLD', 'MACHINERY', 'BUILDING')\n), joined AS (\n  SELECT\n    pf.p_partkey,\n    pf.p_name,\n    pf.p_type,\n    pf.p_container,\n    olc.l_orderkey,\n    olc.l_suppkey,\n    olc.l_quantity,\n    olc.l_extendedprice,\n    olc.l_discount,\n    olc.l_shipmode,\n    olc.o_orderdate,\n    olc.o_orderpriority,\n    olc.o_totalprice,\n    olc.c_custkey,\n    olc.c_name,\n    olc.c_mktsegment,\n    olc.c_acctbal\n  FROM (\n    SELECT\n      pb.p_partkey,\n      pb.p_name,\n      pb.p_type,\n      pb.p_container,\n      pb.p_size\n    FROM (\n      SELECT\n        p.p_partkey,\n        p.p_name,\n        p.p_type,\n        p.p_container,\n        p.p_size\n      FROM part AS p\n      JOIN (\n        SELECT DISTINCT\n          l_partkey\n        FROM orders_lineitem_customer\n        ORDER BY\n          l_partkey ASC\n        LIMIT 200\n      ) AS k\n        ON k.l_partkey = p.p_partkey\n      WHERE\n        p.p_size BETWEEN 5 AND 28\n        AND p.p_container IN ('SM BOX', 'MED BOX', 'LG BOX', 'SM CASE')\n    ) AS pb\n    WHERE\n      SEMANTIC_FILTER(\n        'Does this part look suitable for customer-facing distribution based on name, type, and packaging?\nPart Name: {0}\nPart Type: {1}\nContainer: {2}\nReturn a single YES or NO, with no other words. If uncertain, return YES.',\n        CAST(pb.p_name AS TEXT),\n        CAST(pb.p_type AS TEXT),\n        CAST(pb.p_container AS TEXT)\n      )\n  ) AS pf\n  JOIN orders_lineitem_customer AS olc\n    ON olc.l_partkey = pf.p_partkey\n)\nSELECT\n  *\nFROM joined AS j\nJOIN (\n  SELECT\n    s.s_suppkey,\n    s.s_name,\n    s.s_address,\n    s.s_nationkey,\n    s.s_phone,\n    s.s_acctbal,\n    s.s_comment\n  FROM supplier AS s\n  JOIN (\n    SELECT DISTINCT\n      l_suppkey\n    FROM joined\n    ORDER BY\n      l_suppkey ASC\n    LIMIT 40\n  ) AS k\n    ON k.l_suppkey = s.s_suppkey\n  WHERE\n    SEMANTIC_FILTER(\n      'Does this supplier appear qualified for consumer-facing distribution partnerships?\nSupplier Name: {0}\nAccount Balance: {1}\nComment: {2}\nReturn a single YES or NO, with no other words. If uncertain, return YES.',\n      CAST(s.s_name AS TEXT),\n      CAST(s.s_acctbal AS TEXT),\n      CAST(s.s_comment AS TEXT)\n    )\n) AS sc\n  ON sc.s_suppkey = j.l_suppkey\n  AND SEMANTIC_JOIN(\n    'Would this supplier be suitable for retail distribution of this product?\nPart Type: {0}\nShip Mode: {1}\nCustomer Segment: {2}\nSupplier Name: {3}\nAccount Balance: {4}\nComment: {5}\nReturn a single YES or NO, with no other words. If uncertain, return YES.',\n    CAST(j.p_type AS TEXT),\n    CAST(j.l_shipmode AS TEXT),\n    CAST(j.c_mktsegment AS TEXT),\n    CAST(sc.s_name AS TEXT),\n    CAST(sc.s_acctbal AS TEXT),\n    CAST(sc.s_comment AS TEXT)\n  );\n"

def run(tables, job, model=None):
    from experiments.validation.faithful_runtime import run_lotus_relational
    return run_lotus_relational(RELATIONAL_SQL, tables, job, model=model)

if __name__ == '__main__':
    from experiments.validation.faithful_runtime import query_main
    query_main(globals())
